package ug.fuggieprints.app;
import android.Manifest;import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.webkit.*;import android.view.*;import android.widget.*;import android.print.PrintManager;import java.io.*;import java.util.*;
public class MainActivity extends Activity {
 private WebView web;private ValueCallback<Uri[]> chooser;private static final String HOST="app.fuggieprints.local";private boolean remote=false;
 @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout layout=new LinearLayout(this);layout.setOrientation(LinearLayout.VERTICAL);web=new WebView(this);layout.addView(web,new LinearLayout.LayoutParams(-1,-1));setContentView(layout);layout.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i.consumeSystemWindowInsets();});WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setMediaPlaybackRequiresUserGesture(true);s.setSupportMultipleWindows(false);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);web.setWebViewClient(new WebViewClient(){@Override public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest req){Uri u=req.getUrl();if(!HOST.equals(u.getHost()))return null;try{String p=u.getPath();if(p==null||p.equals("/"))p="/index.html";if(p.contains(".."))return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));String name=p.substring(1);String mime=name.endsWith(".html")?"text/html":name.endsWith(".css")?"text/css":name.endsWith(".js")?"application/javascript":name.endsWith(".png")?"image/png":name.endsWith(".jpeg")?"image/jpeg":"application/octet-stream";WebResourceResponse result=new WebResourceResponse(mime,"UTF-8",getAssets().open("public/"+name));Map<String,String> headers=new HashMap<>();headers.put("Content-Security-Policy","default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' blob: data:; connect-src 'self' https:; frame-src https://newnesscaesar-coder.github.io https://www.youtube.com; object-src 'none'; base-uri 'self'");result.setResponseHeaders(headers);return result;}catch(IOException e){return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream("Not found".getBytes()));}}@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest req){if(!req.isForMainFrame())return false;Uri u=req.getUrl();if("fuggie".equals(u.getScheme())){if("website".equals(u.getHost()))openRemote("https://newnesscaesar-coder.github.io/Fuggie-Prints/index.html");else if("social".equals(u.getHost())){String target=u.getQueryParameter("url");if(validSocial(target))openRemote(target);}else if("print".equals(u.getHost()))print();return true;}if(HOST.equals(u.getHost())&&"https".equals(u.getScheme())){remote=false;return false;}if(remote&&"https".equals(u.getScheme())&&(u.getHost().equals("newnesscaesar-coder.github.io")||validSocial(u.toString())))return false;if(Arrays.asList("https","mailto","tel").contains(u.getScheme())){try{startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(ActivityNotFoundException e){Toast.makeText(MainActivity.this,"No app available to open this link",Toast.LENGTH_LONG).show();}return true;}return true;}@Override public void onPageFinished(WebView v,String url){if(remote&&url.startsWith("https://newnesscaesar-coder.github.io/Fuggie-Prints/"))v.evaluateJavascript("(()=>{if(matchMedia('(prefers-reduced-motion:reduce)').matches)return;let style=document.createElement('style');style.textContent='.fuggie-reveal{opacity:0;transform:translateY(24px);transition:opacity .75s ease .2s,transform .75s ease .2s}.fuggie-reveal.shown{opacity:1;transform:none}';document.head.append(style);let ob=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('shown');ob.unobserve(e.target)}}),{threshold:.05});document.querySelectorAll('main section').forEach(e=>{e.classList.add('fuggie-reveal');ob.observe(e)})})()",null);}});web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> cb,FileChooserParams params){if(chooser!=null)chooser.onReceiveValue(null);chooser=cb;Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.setType("*/*");intent.addCategory(Intent.CATEGORY_OPENABLE);intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);try{startActivityForResult(intent,22);}catch(ActivityNotFoundException e){chooser.onReceiveValue(null);chooser=null;return false;}return true;}});web.loadUrl("https://"+HOST+"/index.html");ReminderReceiver.createChannel(this);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},12);ReminderReceiver.scheduleAll(this);}
 private boolean validSocial(String value){if(value==null)return false;Uri u=Uri.parse(value);String h=u.getHost();return "https".equals(u.getScheme())&&h!=null&&(h.equals("x.com")||h.equals("www.youtube.com")||h.equals("youtube.com")||h.equals("www.tiktok.com")||h.equals("www.instagram.com"));}private void openRemote(String url){remote=true;web.loadUrl(url);}private void print(){((PrintManager)getSystemService(PRINT_SERVICE)).print("Fuggie Prints document",web.createPrintDocumentAdapter("Fuggie Prints"),null);}
 @Override public boolean onCreateOptionsMenu(Menu menu){menu.add("Back to app").setShowAsAction(MenuItem.SHOW_AS_ACTION_ALWAYS);return true;}@Override public boolean onOptionsItemSelected(MenuItem item){remote=false;web.loadUrl("https://"+HOST+"/index.html");return true;}
 @Override public void onBackPressed(){if(remote){remote=false;web.loadUrl("https://"+HOST+"/index.html#videos");}else if(web.canGoBack())web.goBack();else super.onBackPressed();}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==22&&chooser!=null){Uri[] uris=null;if(result==RESULT_OK&&data!=null){if(data.getClipData()!=null){int n=data.getClipData().getItemCount();uris=new Uri[n];for(int i=0;i<n;i++)uris[i]=data.getClipData().getItemAt(i).getUri();}else if(data.getData()!=null)uris=new Uri[]{data.getData()};}chooser.onReceiveValue(uris);chooser=null;}}
 @Override protected void onDestroy(){web.destroy();super.onDestroy();}
}
